QPixmap teammateAvatarArt(const QString &avatar, const QString &provider,
                          const QString &model, int side, bool *portrait)
{
    if (portrait)
        *portrait = false;
    static const QHash<QString, QString> teammateArt{
        {QStringLiteral("cfo"),
         QStringLiteral(":/agent-ui/icons/teammate-cfo.png")},
        {QStringLiteral("code-steward"),
         QStringLiteral(":/agent-ui/icons/teammate-code-steward.png")},
        {QStringLiteral("marketing"),
         QStringLiteral(":/agent-ui/icons/teammate-marketing.png")},
        {QStringLiteral("mobile-developer"),
         QStringLiteral(":/agent-ui/icons/teammate-mobile-developer.png")},
        {QStringLiteral("quality"),
         QStringLiteral(":/agent-ui/icons/teammate-quality.png")},
        {QStringLiteral("ux"),
         QStringLiteral(":/agent-ui/icons/teammate-ux.png")},
        {QStringLiteral("ceo"),
         QStringLiteral(":/agent-ui/icons/teammate-ceo.png")},
        {QStringLiteral("sage"),
         QStringLiteral(":/agent-ui/icons/teammate-sage.png")},
        {QStringLiteral("coo"),
         QStringLiteral(":/agent-ui/icons/teammate-coo.png")},
        {QStringLiteral("cpa"),
         QStringLiteral(":/agent-ui/icons/teammate-cpa.png")},
        {QStringLiteral("fixer"),
         QStringLiteral(":/agent-ui/icons/teammate-fixer.png")},
        {QStringLiteral("tempo"),
         QStringLiteral(":/agent-ui/icons/teammate-tempo.png")},
        {QStringLiteral("reaper"),
         QStringLiteral(":/agent-ui/icons/teammate-reaper.png")},
        {QStringLiteral("sales"),
         QStringLiteral(":/agent-ui/icons/teammate-sales.png")},
        {QStringLiteral("yc-news"),
         QStringLiteral(":/agent-ui/icons/teammate-yc-news.png")},
        {QStringLiteral("sentinel"),
         QStringLiteral(":/agent-ui/icons/teammate-sentinel.png")},
        {QStringLiteral("hearth"),
         QStringLiteral(":/agent-ui/icons/teammate-hearth.png")},
        {QStringLiteral("reddit"),
         QStringLiteral(":/agent-ui/icons/teammate-reddit.png")},
        {QStringLiteral("blogger"),
         QStringLiteral(":/agent-ui/icons/teammate-blogger.png")},
        {QStringLiteral("herald"),
         QStringLiteral(":/agent-ui/icons/teammate-herald.png")},
        {QStringLiteral("crawler"),
         QStringLiteral(":/agent-ui/icons/teammate-crawler.png")},
    };
    if (avatar == QLatin1String("genie")) {
        QPixmap spider(side * 2, side * 2);
        spider.fill(Qt::transparent);
        QPainter painter(&spider);
        painter.setRenderHint(QPainter::Antialiasing, true);
        QRadialGradient glow(QPointF(side, side * 0.9), side * 1.2);
        glow.setColorAt(0, QColor(58, 34, 104));
        glow.setColorAt(1, QColor(10, 14, 30));
        painter.fillRect(spider.rect(), glow);
        GenieSpiderPose pose;
        pose.vitality = 0.9;
        pose.condition = GenieVitalLevel::Thriving;
        GenieSpiderPainter::paint(painter, QRectF(side * 0.2, side * 0.16, side * 1.6, side * 1.6), pose);
        return spider;
    }
    QPixmap art;
    if (teammateArt.contains(avatar)) {
        art.load(teammateArt.value(avatar));
        if (portrait)
            *portrait = !art.isNull();
    } else {
        static const QHash<QString, int> fixed{
            {QStringLiteral("opus"), 0}, {QStringLiteral("sonnet"), 1},
            {QStringLiteral("haiku"), 2}, {QStringLiteral("fable"), 3},
            {QStringLiteral("sol"), 4}, {QStringLiteral("luna"), 5},
            {QStringLiteral("terra"), 6},
        };
        const QIcon icon = fixed.contains(avatar)
                               ? agentControlIcon(fixed.value(avatar))
                               : agentModelIcon(provider, model);
        art = icon.pixmap(side * 2, side * 2);
    }
    if (art.isNull())
        art = agentControlIcon(4).pixmap(side * 2, side * 2);
    return art;
}

