QPixmap teammateAvatarPixmap(const QString &avatarKey,
                                    const QString &provider,
                                    const QString &model, int side)
{
    const QString avatar = avatarKey.trimmed().toLower();
    static QHash<QString, QPixmap> cache;
    const QString cacheKey = avatar + QLatin1Char('|') + provider +
                             QLatin1Char('|') + model + QLatin1Char('|') +
                             QString::number(side) + QLatin1Char('|') +
                             QString::number(iconDevicePixelRatio());
    const auto cached = cache.constFind(cacheKey);
    if (cached != cache.constEnd())
        return cached.value();
    const QPixmap portrait =
        roundedAvatar(teammateAvatarArt(avatar, provider, model, side, nullptr), side, 0.5);
    cache.insert(cacheKey, portrait);
    return portrait;
}

QPixmap teammateFacePixmap(const QString &avatarKey, const QString &provider,
                           const QString &model, int side)
{
    const QString avatar = avatarKey.trimmed().toLower();
    static QHash<QString, QPixmap> cache;
    const QString cacheKey = avatar + QLatin1Char('|') + provider +
                             QLatin1Char('|') + model + QLatin1Char('|') +
                             QString::number(side) + QLatin1Char('|') +
                             QString::number(iconDevicePixelRatio());
    const auto cached = cache.constFind(cacheKey);
    if (cached != cache.constEnd())
        return cached.value();
    bool portrait = false;
    QPixmap art = teammateAvatarArt(avatar, provider, model, side * 2, &portrait);
    art.setDevicePixelRatio(1.0);
    QRectF source(QPointF(0, 0), QSizeF(art.size()));
    if (portrait) {
        const qreal span = qMin(source.width(), source.height()) * 0.62;
        source = QRectF(source.width() * 0.5 - span / 2,
                        source.height() * 0.46 - span / 2, span, span);
    }
    const qreal dpr = iconDevicePixelRatio();
    QPixmap out = crispIconPixmap(side, dpr);
    QPainter painter(&out);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setRenderHint(QPainter::SmoothPixmapTransform);
    painter.drawPixmap(QRectF(0, 0, side, side), art, source);
    painter.end();
    cache.insert(cacheKey, out);
    return out;
}

QPixmap nodeMachineFavicon(const QString &seed, int side)
{
    QPixmap pm = roundedAvatar(forkMeshNodeAvatarPng(seed), side);
    if (!pm.isNull())
        return pm;
    return QPixmap();
}

QIcon osBadgeIcon(const QString &platform, bool online, int size)
{
    // Pure function of (platform family, online, size, DPR). The nodes
    // table, the node detail panel and the chat member cards each rebuild
    // one per row/card on every roster tick, so keep the drawn icon.
    static QHash<QString, QIcon> cache;
    const QString p = platform.toLower();
    const QString key = p + QLatin1Char('|') + (online ? QLatin1Char('1') : QLatin1Char('0')) +
                        QLatin1Char('|') + QString::number(size) + QLatin1Char('|') +
                        QString::number(iconDevicePixelRatio());
    const auto cached = cache.constFind(key);
    if (cached != cache.constEnd())
        return cached.value();
    const QColor grey = Theme::remapColor(QColor("#6e7681"));
    const QColor online_green("#2ea043");
    auto col = [&](const QColor &) { return online ? online_green : grey; };

    QPixmap pm = crispIconPixmap(size, iconDevicePixelRatio());
    QPainter g(&pm);
    g.setRenderHint(QPainter::Antialiasing);
    g.setPen(Qt::NoPen);

    if (p.contains("win")) {
        g.setBrush(col(QColor("#3fa0ef")));
        const qreal m = size * 0.18, gap = size * 0.12;
        const qreal cell = (size - 2 * m - gap) / 2.0;
        g.drawRect(QRectF(m, m, cell, cell));
        g.drawRect(QRectF(m + cell + gap, m, cell, cell));
        g.drawRect(QRectF(m, m + cell + gap, cell, cell));
        g.drawRect(QRectF(m + cell + gap, m + cell + gap, cell, cell));
    } else if (p.contains("mac") || p.contains("ios") || p.contains("darwin") ||
               p.contains("os x")) {
        g.setBrush(col(QColor("#c7ccd1")));
        QPainterPath body;
        body.addEllipse(QPointF(size * 0.46, size * 0.60), size * 0.30, size * 0.33);
        QPainterPath bite;
        bite.addEllipse(QPointF(size * 0.88, size * 0.52), size * 0.17, size * 0.20);
        g.drawPath(body.subtracted(bite));
        g.save();
        g.translate(size * 0.56, size * 0.22);
        g.rotate(-35);
        g.drawEllipse(QPointF(0, 0), size * 0.13, size * 0.07);
        g.restore();
    } else if (p.contains("linux") || p.contains("bsd") || p.contains("unix")) {
        g.setBrush(col(QColor("#2b2b2b")));
        g.drawEllipse(QPointF(size * 0.5, size * 0.54), size * 0.30, size * 0.40);
        g.setBrush(online ? QColor("#f5f5f5") : QColor("#cfcfcf"));
        g.drawEllipse(QPointF(size * 0.5, size * 0.62), size * 0.17, size * 0.26);
        g.setBrush(col(QColor("#f0a020")));
        QPainterPath beak;
        beak.moveTo(size * 0.5, size * 0.32);
        beak.lineTo(size * 0.40, size * 0.40);
        beak.lineTo(size * 0.60, size * 0.40);
        beak.closeSubpath();
        g.drawPath(beak);
    } else {
        g.setBrush(col(Theme::remapColor(QColor("#8b949e"))));
        const qreal m = size * 0.16;
        g.drawRoundedRect(QRectF(m, m, size - 2 * m, size * 0.5),
                          size * 0.06, size * 0.06);
        g.drawRect(QRectF(size * 0.44, m + size * 0.5, size * 0.12, size * 0.14));
        g.drawRoundedRect(QRectF(size * 0.30, size * 0.80, size * 0.40, size * 0.07),
                          size * 0.03, size * 0.03);
    }
    g.end();
    const QIcon icon(pm);
    if (cache.size() > 256)
        cache.clear(); // platform strings are free-form; keep it bounded
    cache.insert(key, icon);
    return icon;
}

