int railCaptionItemWidth()
{
    static const int width = [] {
        QFont f = QGuiApplication::font();
        f.setPixelSize(10);
        f.setWeight(QFont::DemiBold);
        const QFontMetrics metrics(f);
        int widest = kRailItemWidth;
        for (const char *caption :
             {"Agents", "Code", "Git", "Repos", "Market", "Chat",
              "Control", "Network", "Settings", "Log", "Capture",
              "Resize", "Restart", "Tasks", "Pings", "Account"})
            widest = qMax(widest, metrics.horizontalAdvance(
                                      QString::fromLatin1(caption)) + 4);
        return widest;
    }();
    return width;
}

int railCompactItemWidth()
{
    return railCaptionsHidden() ? kRailItemWidth : railCaptionItemWidth();
}

