{
    return railCompactItemWidth();
}

int railColumnWidth()
{
    return railExpanded() ? railExpandedItemWidth() : railCompactItemWidth();
}

int railWidth()
{ return railColumnWidth() + 6; }

QFont navBalanceFont()
{
    static const QFont font = [] {
        QFont f = QGuiApplication::font();
        f.setWeight(QFont::Normal);
        for (int px = 9; px > 6; --px) {
            f.setPixelSize(px);
            // Sized against the narrowest rail the app can show (captions off)
            // so the cached font stays legible in both modes.
            if (QFontMetrics(f).horizontalAdvance(
                    QStringLiteral("0.0000 SOL")) <= kRailItemWidth)
                return f;
        }
        f.setPixelSize(6);
        return f;
    }();
    return font;
}

int navBalanceLineHeight()
{
    static const int height = QFontMetrics(navBalanceFont()).height() + 2;
    return height;
}

